import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"编译与部署","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"},{"text":"simplified key二进制配置JSON","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/simplified_key_json_configuration"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/simplified_key_json_configuration.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/simplified_key_json_configuration.md","outlineHeaders":[{"level":2,"title":"JSON如何提供","slug":"JSON如何提供","link":"#JSON如何提供"},{"level":2,"title":"JSON格式","slug":"JSON格式","link":"#JSON格式"},{"level":2,"title":"对编译过程的影响","slug":"对编译过程的影响","link":"#对编译过程的影响"},{"level":2,"title":"与普通编译的关系","slug":"与普通编译的关系","link":"#与普通编译的关系"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787886219000}'),l={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/simplified_key_json_configuration.md"};function e(o,s,t,d,i,u){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>simplified key二进制配置JSON</h1><p>本文介绍在自定义算子工程中如何提供核函数（Kernel）二进制配置JSON，以及该JSON如何驱动按自定义simplified key编译多份binary。该机制适用于一个OpType需要按dtype、format、shape分档或属性组合预编译多份binary，并由运行时根据<code>GenSimplifiedKey</code>回调选择的场景。</p><p>回调的编写和注册方式见<a href="../design_and_implementation/gen_simplified_key.html">GenSimplifiedKey回调实现</a>，运行时选择过程见<a href="../invocation/simplified_key_runtime_flow.html">基于simplified key的运行时选择流程</a>。</p><h2 id="JSON如何提供">JSON如何提供<a class="header-anchor" href="#JSON如何提供">​</a></h2><p>将JSON放在算子工程现有的Host侧配置目录中，并按AI处理器型号划分。例如<code>AddCustomTemplate</code>样例使用：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>op_host/config/ascendxxx/add_custom_template_binary.json
</code></pre></div><p>在<code>op_kernel/CMakeLists.txt</code>中通过<code>npu_op_kernel_options()</code>传递<code>--kernel-json-file</code>。该参数属于编译选项，不写入<code>npu_op_kernel_sources()</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustomTemplate</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">add_custom_template</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom_template.cpp</span>
<span class="p">)</span>

<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustomTemplate</span>
<span class="w">    </span><span class="s">OPTIONS</span>
<span class="w">        </span><span class="s">--kernel-json-file=</span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="s">/../op_host/config/ascendxxx/add_custom_template_binary.json</span>
<span class="p">)</span>
</code></pre></div><p>构建配置阶段会将该选项记录到自动生成的<code>custom_opc_options.ini</code>，后续二进制编译从该文件读取。例如：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>AddCustomTemplate@@--kernel-json-file=&lt;工程路径&gt;/op_host/config/ascendxxx/add_custom_template_binary.json
</code></pre></div><h2 id="JSON格式">JSON格式<a class="header-anchor" href="#JSON格式">​</a></h2><p>JSON文件最外层包含<code>op_type</code>和<code>op_list</code>两个字段：<code>op_type</code>指定算子类型，<code>op_list</code>中的每个元素描述一份待编译的binary。以下是<code>AddCustomTemplate</code>的完整示例，按FP16和FP32生成两份binary：</p><div class="code-block"><div class="code-header"><span class="lang-label">JSON</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="p">{</span>
<span class="w">  </span><span class="nt">&quot;op_type&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;AddCustomTemplate&quot;</span><span class="p">,</span>
<span class="w">  </span><span class="nt">&quot;op_list&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span>
<span class="w">    </span><span class="p">{</span>
<span class="w">      </span><span class="nt">&quot;bin_filename&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;AddCustomTemplate_FP16&quot;</span><span class="p">,</span>
<span class="w">      </span><span class="nt">&quot;simplified_key&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;custom_fp16&quot;</span><span class="p">,</span>
<span class="w">      </span><span class="nt">&quot;inputs&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span>
<span class="w">        </span><span class="p">{</span>
<span class="w">          </span><span class="nt">&quot;name&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;x&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;index&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;dtype&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;float16&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;format&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ND&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;shape&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="mi">-2</span><span class="p">]</span>
<span class="w">        </span><span class="p">},</span>
<span class="w">        </span><span class="p">{</span>
<span class="w">          </span><span class="nt">&quot;name&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;y&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;index&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;dtype&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;float16&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;format&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ND&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;shape&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="mi">-2</span><span class="p">]</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">      </span><span class="p">],</span>
<span class="w">      </span><span class="nt">&quot;outputs&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span>
<span class="w">        </span><span class="p">{</span>
<span class="w">          </span><span class="nt">&quot;name&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;z&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;index&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;dtype&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;float16&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;format&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ND&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;shape&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="mi">-2</span><span class="p">]</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">      </span><span class="p">]</span>
<span class="w">    </span><span class="p">},</span>
<span class="w">    </span><span class="p">{</span>
<span class="w">      </span><span class="nt">&quot;bin_filename&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;AddCustomTemplate_FP32&quot;</span><span class="p">,</span>
<span class="w">      </span><span class="nt">&quot;simplified_key&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;custom_fp32&quot;</span><span class="p">,</span>
<span class="w">      </span><span class="nt">&quot;inputs&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span>
<span class="w">        </span><span class="p">{</span>
<span class="w">          </span><span class="nt">&quot;name&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;x&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;index&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;dtype&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;float32&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;format&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ND&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;shape&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="mi">-2</span><span class="p">]</span>
<span class="w">        </span><span class="p">},</span>
<span class="w">        </span><span class="p">{</span>
<span class="w">          </span><span class="nt">&quot;name&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;y&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;index&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;dtype&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;float32&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;format&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ND&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;shape&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="mi">-2</span><span class="p">]</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">      </span><span class="p">],</span>
<span class="w">      </span><span class="nt">&quot;outputs&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span>
<span class="w">        </span><span class="p">{</span>
<span class="w">          </span><span class="nt">&quot;name&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;z&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;index&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;dtype&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;float32&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;format&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ND&quot;</span><span class="p">,</span>
<span class="w">          </span><span class="nt">&quot;shape&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="mi">-2</span><span class="p">]</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">      </span><span class="p">]</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">  </span><span class="p">]</span>
<span class="p">}</span>
</code></pre></div><p>字段说明如下：</p><p><strong>表1</strong> simplified key二进制配置JSON字段说明</p><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>op_type</code></td><td>必填，必须与<code>npu_op_kernel_sources()</code>中的<code>OP_TYPE</code>一致。</td></tr><tr><td><code>op_list</code></td><td>必填非空数组；数组中的每一项对应一份独立编译的binary。</td></tr><tr><td><code>bin_filename</code></td><td>必填，不含目录；用于生成<code>.o</code>和配套<code>.json</code>文件名。去掉扩展名后必须等于<code>\${op_type}</code>或以<code>\${op_type}_</code>开头，其中<code>\${op_type}</code>为大驼峰风格的算子名，且文件名不能重复。</td></tr><tr><td><code>simplified_key</code></td><td>必填非空字符串；是<code>GenSimplifiedKey</code>回调返回的自定义片段，必须与回调逐字节一致；字符串经UTF-8编码后的长度必须小于256字节。</td></tr><tr><td><code>inputs</code>、<code>outputs</code></td><td>每个输入输出包含<code>name</code>、<code>index</code>、<code>dtype</code>、<code>format</code>和<code>shape</code>，描述本项binary支持的组合。</td></tr></tbody></table><p><code>name</code>和<code>index</code>必须与算子原型定义的输入输出顺序一致；<code>dtype</code>和<code>format</code>必须属于原型声明的支持范围；<code>shape</code>应表达该binary覆盖的shape范围。JSON解析会检查最外层结构、<code>op_type</code>、非空<code>op_list</code>、<code>bin_filename</code>和<code>simplified_key</code>等基本格式，后续<code>asc_opc</code>编译还会依据输入输出描述处理具体组合。因此，JSON中的组合必须与原型定义、核函数（Kernel）实现和回调分支保持一致。</p><h2 id="对编译过程的影响">对编译过程的影响<a class="header-anchor" href="#对编译过程的影响">​</a></h2><p>配置JSON后，编译链路按以下顺序工作：</p><ol><li>CMake将<code>--kernel-json-file</code>写入<code>custom_opc_options.ini</code>。</li><li>二进制构建读取JSON，按<code>op_list</code>拆分为单组合JSON；每一项使用自身的<code>bin_filename</code>作为输出名称。</li><li>对每个单组合JSON调用<code>asc_opc</code>编译核函数（Kernel）源码，得到对应的<code>.o</code>和描述该<code>.o</code>的<code>.json</code>。</li><li>JSON中存在非空<code>simplified_key</code>时，<code>asc_opc</code>使用自定义simplified key模式2，并将算子类型、运行时公共维度和该片段组合为完整simplified key。</li><li>汇总阶段生成算子配置JSON和<code>binary_info_config.json</code>，记录每个完整Key关联的<code>.o</code>与<code>.json</code>路径。</li></ol><p>以FP16项为例，主要产物如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>binary/ascendxxx/add_custom_template/AddCustomTemplate_FP16.o
binary/ascendxxx/add_custom_template/AddCustomTemplate_FP16.json
binary/config/ascendxxx/add_custom_template.json
binary/config/ascendxxx/binary_info_config.json
</code></pre></div><p>其中<code>AddCustomTemplate_FP16.json</code>记录单份<code>.o</code>的核函数（Kernel）元信息；<code>add_custom_template.json</code>汇总每个组合的支持信息；<code>binary_info_config.json</code>为运行时提供完整simplified key到binary路径的查找表。示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">JSON</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="p">{</span>
<span class="w">  </span><span class="nt">&quot;AddCustomTemplate&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="nt">&quot;simplifiedKeyMode&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span>
<span class="w">    </span><span class="nt">&quot;binaryList&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span>
<span class="w">      </span><span class="p">{</span>
<span class="w">        </span><span class="nt">&quot;simplifiedKey&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="s2">&quot;AddCustomTemplate/d=0,p=1/custom_fp16&quot;</span><span class="p">],</span>
<span class="w">        </span><span class="nt">&quot;binPath&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ascendxxx/add_custom_template/AddCustomTemplate_FP16.o&quot;</span><span class="p">,</span>
<span class="w">        </span><span class="nt">&quot;jsonPath&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ascendxxx/add_custom_template/AddCustomTemplate_FP16.json&quot;</span>
<span class="w">      </span><span class="p">},</span>
<span class="w">      </span><span class="p">{</span>
<span class="w">        </span><span class="nt">&quot;simplifiedKey&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span><span class="s2">&quot;AddCustomTemplate/d=0,p=1/custom_fp32&quot;</span><span class="p">],</span>
<span class="w">        </span><span class="nt">&quot;binPath&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ascendxxx/add_custom_template/AddCustomTemplate_FP32.o&quot;</span><span class="p">,</span>
<span class="w">        </span><span class="nt">&quot;jsonPath&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ascendxxx/add_custom_template/AddCustomTemplate_FP32.json&quot;</span>
<span class="w">      </span><span class="p">}</span>
<span class="w">    </span><span class="p">]</span>
<span class="w">  </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>实际产物可能针对确定性和实现模式写入多个完整Key；它们共享同一个自定义片段和binary路径。算子开发者不应在回调中手动拼接<code>AddCustomTemplate/d=0,p=1/</code>等前缀。</p><h2 id="与普通编译的关系">与普通编译的关系<a class="header-anchor" href="#与普通编译的关系">​</a></h2><p>不配置<code>--kernel-json-file</code>且不注册<code>GenSimplifiedKey</code>时，算子继续使用原有编译和binary匹配流程。只有同时满足“JSON为每个组合提供非空<code>simplified_key</code>”和“Host侧注册相应回调”时，运行时才具备自定义simplified key选择所需的两端信息。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./basic_process.html">编译与部署基本流程</a>：了解通用的工程构建、打包和部署流程。</li><li><a href="../design_and_implementation/gen_simplified_key.html">GenSimplifiedKey回调实现</a>：了解回调返回值如何与JSON中的<code>simplified_key</code>对应。</li><li><a href="../invocation/simplified_key_runtime_flow.html">基于simplified key的运行时选择流程</a>：了解运行时如何使用<code>binary_info_config.json</code>查找binary。</li></ul></article></div>`,1)])])}const r=a(l,[["render",e]]);export{_ as __pageData,r as default};
